// Category B — one line of an order: the item, the options chosen for it, any discounts on it, its
// price, and the actions that change it (quantity, options, remove). Every ordering surface draws
// this line (a POS cart pane, a terminal cart sheet, a kiosk cart, a table order cart, a dashboard
// order drawer), and CartSummary's `{name, quantity,
// price}` items carry none of options, discounts or controls.
//
// A Component, not a Block: the option line is muted ink, a discount line carries its own ink and an
// earlier round is muted as a whole, and a Block owns no colour (block-contract.md §5).
//
// Selection is not here. Lines that can be selected sit in a GridList, and a screen that shows the
// controls only on the selected line (POS) passes `isReadOnly` to the rest. Mine and members' lines,
// or this round and earlier rounds, are GridList sections.
//
// A GridList that holds editable lines must set `keyboardNavigationBehavior="tab"`. With the default
// `arrow`, React Aria's row captures the arrow keys from every descendant (useGridListItem), so the
// quantity spinbutton never steps, the caret cannot move in its input, and focus jumps rows.
//
// `controls` places the controls. `end` (the default) sets remove at the line's end and the stepper
// along the bottom, as a kiosk or table-order cart does. `top` sets them in a row above the
// summary, the stepper at the start and a worded remove at the end, as a POS cart's selected line
// does; the stepper is then NumberField's split layout, − n +, and the name keeps its "× n".
//
// Every action comes with its accessible name, enforced by the types: omit both, or pass both. A
// conditional handler (`onRemove={canRemove ? remove : undefined}` beside a fixed label) does not
// compile; spread the pair conditionally instead.
//
// In a GridList, give each row a `textValue` that carries the name, the quantity and the price. React
// Aria names the row by its `textValue`, so a focused row is heard as that string alone, and the
// line's hidden labels are reached only by reading inside the row.
import { X } from "./icons";
import type { ReactNode, Ref } from "react";
import { Button } from "./Button";
import { NumberField } from "./NumberField";
import { roleSize, type ControlSize } from "./controlSize";
import "./OrderLine.css";

type OrderLineSize = ControlSize;

/** A discount applied to the line, e.g. 「쿠폰 할인 -1,000원」. */
export type OrderLineDiscount = {
  /** Stable key. */
  id: string;
  /** What the discount is, e.g. "쿠폰 할인". */
  label: ReactNode;
  /** The deduction as shown, e.g. "-1,000원". */
  amount: string;
} & (
  | {
      /** Removes the discount. */
      onRemove: () => void;
      /** Accessible name of the remove button, e.g. "아메리카노 쿠폰 할인 삭제". */
      removeLabel: string;
    }
  | { onRemove?: undefined; removeLabel?: undefined }
);

export interface OrderLineBaseProps {
  /**
   * Size axis: the type rung and the size of every control.
   *
   * @default "medium"
   */
  size?: OrderLineSize;
  /** The item's name. */
  name: ReactNode;
  /** The chosen options as one line, e.g. "ICED / 샷 추가 (+500원)". */
  options?: ReactNode;
  /** Discounts on this line, each on its own sub-line. */
  discounts?: OrderLineDiscount[];
  /** The line's price as shown, after quantity and options, e.g. "9,000원". */
  price: string;
  /** How many. */
  quantity: number;
  /** Called with the new quantity from the stepper. Without it there is no stepper. */
  onQuantityChange?: (quantity: number) => void;
  /** The most the stepper allows, e.g. a stock count or a per-order limit. */
  maxQuantity?: number;
  /**
   * Names the quantity: the stepper's accessible name, and read with the count on a read-only line.
   * In a list of several lines make it item-specific ("아메리카노 수량"), so each stepper is told apart.
   */
  quantityLabel: string;
  /**
   * When true, no controls render and the quantity shows as text: a mirror on the customer display,
   * a payment detail, a line the person cannot edit.
   */
  isReadOnly?: boolean;
  /** When true, the line is an earlier round already sent: muted and read-only. */
  isMuted?: boolean;
  /**
   * Where the controls sit: `end` (remove at the end, stepper along the bottom) or `top` (a row above
   * the summary: split stepper at the start, worded remove at the end, as on the POS cart).
   *
   * @default "end"
   */
  controls?: "end" | "top";
}

export type OrderLineProps = OrderLineBaseProps &
  (
    | {
        /** The price before a discount, shown struck through above `price`. */
        originalPrice: string;
        /** Read before the struck price, which is otherwise silent, e.g. "할인 전 가격". */
        originalPriceLabel: string;
      }
    | { originalPrice?: undefined; originalPriceLabel?: undefined }
  ) &
  (
    | {
        /** Opens the option editor. */
        onChangeOptions: () => void;
        /** Visible label of the change-options button, e.g. "옵션 변경". */
        changeOptionsLabel: string;
      }
    | { onChangeOptions?: undefined; changeOptionsLabel?: undefined }
  ) &
  (
    | {
        /** Removes the line. */
        onRemove: () => void;
        /** Accessible name of the remove button, e.g. "아메리카노 삭제". */
        removeLabel: string;
        /** Visible word on the remove button, e.g. "삭제". Without it the button is an icon. */
        removeText?: string;
      }
    | { onRemove?: undefined; removeLabel?: undefined; removeText?: undefined }
  ) & {
    /** Additional class (optional). sd-order-line is always preserved. */
    className?: string;
    /** Forwarded to the root element. */
    ref?: Ref<HTMLDivElement>;
  };

export function OrderLine({
  size = "medium",
  name,
  options,
  discounts = [],
  price,
  originalPrice,
  originalPriceLabel,
  quantity,
  onQuantityChange,
  maxQuantity,
  quantityLabel,
  onChangeOptions,
  changeOptionsLabel,
  onRemove,
  removeLabel,
  isReadOnly = false,
  isMuted = false,
  controls = "end",
  removeText,
  className,
  ref,
}: OrderLineProps) {
  const editable = !isReadOnly && !isMuted;
  const stepper = editable && onQuantityChange !== undefined;
  const changeOptions = editable && onChangeOptions !== undefined;

  return (
    <div
      ref={ref}
      data-controls={controls}
      className={className ? `sd-order-line ${className}` : "sd-order-line"}
    >
      <div className="sd-order-line__summary" data-controls={controls}>
        <span className={`sd-order-line__name sd-type-body-${roleSize(size)}-emphasized`} data-muted={isMuted || undefined}>
          {name}
          {(!stepper || controls === "top") && (
            <>
              <span className="sd-order-line__quantity" aria-hidden="true"> × {quantity}</span>
              <span className="sd-visually-hidden">, {quantityLabel} {quantity}</span>
            </>
          )}
        </span>
        {options && (
          <span className={`sd-order-line__options sd-type-caption-${roleSize(size)}`}>{options}</span>
        )}
        {discounts.map((d) => (
          <span key={d.id} className={`sd-order-line__discount sd-type-caption-${roleSize(size)}`} data-muted={isMuted || undefined}>
            {d.label} {d.amount}
            {/* small inside a caption line: it still clears the 24 px target (WCAG 2.5.8) */}
            {editable && d.onRemove && (
              <Button isIconOnly variant="ghost" size="small" aria-label={d.removeLabel} onPress={d.onRemove}>
                <X aria-hidden size="1em" />
              </Button>
            )}
          </span>
        ))}
      </div>
      <span className={`sd-order-line__price sd-type-body-${roleSize(size)}-emphasized`} data-controls={controls} data-muted={isMuted || undefined}>
        {originalPrice && (
          <s className={`sd-order-line__original-price sd-type-caption-${roleSize(size)}`}>
            <span className="sd-visually-hidden">{originalPriceLabel} </span>
            {originalPrice}
          </s>
        )}
        {price}
      </span>
      {editable && onRemove && (
        removeText ? (
          // usage: secondary-action — removing the line, worded beside the stepper on the POS cart
          <Button className="sd-order-line__remove" variant="secondary" size={size} aria-label={removeLabel} onPress={onRemove}>
            {removeText}
          </Button>
        ) : (
          <Button
            className="sd-order-line__remove"
            isIconOnly
            variant="ghost"
            size={size}
            aria-label={removeLabel}
            onPress={onRemove}
          >
            <X aria-hidden size="1em" />
          </Button>
        )
      )}
      {(stepper || changeOptions) && (
        <div className="sd-order-line__actions" data-controls={controls}>
          {changeOptions && (
            <Button variant="secondary" size={size} onPress={onChangeOptions}>
              {changeOptionsLabel}
            </Button>
          )}
          {stepper && (
            <NumberField
              className="sd-order-line__stepper"
              // NumberField has no x-small (its steppers do not fit 24px), so an x-small line steps at small.
              size={size === "x-small" ? "small" : size}
              layout={controls === "top" ? "split" : "end"}
              aria-label={quantityLabel}
              value={quantity}
              minValue={1}
              maxValue={maxQuantity}
              onChange={(n) => Number.isFinite(n) && onQuantityChange(n)}
            />
          )}
        </div>
      )}
    </div>
  );
}

/* The summary (name, options, discounts) takes the free width; the price and the remove button sit at
   its end on the first row; the actions (change options, quantity) run along the bottom at the end, as
   a cart line places them. */
.sd-order-line {
  display: grid;
  /* fills the row it is placed in, a GridListItem's flex row included */
  inline-size: 100%;
  grid-template-columns: minmax(0, 1fr) auto auto;
  grid-template-areas:
    "summary price remove"
    "actions actions actions";
  align-items: start;
  column-gap: var(--sd-order-line-gap);
  row-gap: var(--sd-order-line-gap);
}

/* Controls on top: the stepper row above, the summary and price below (the POS cart's selected line). */
.sd-order-line[data-controls="top"] {
  grid-template-areas:
    "actions actions remove"
    "summary price price";
}

.sd-order-line__summary {
  grid-area: summary;
  display: flex;
  flex-direction: column;
  gap: var(--sd-order-line-summary-gap);
  min-inline-size: 0;
}

.sd-order-line__name {
  color: var(--sd-order-line-name-foreground);
  overflow-wrap: anywhere;
}

.sd-order-line__quantity {
  font-variant-numeric: tabular-nums;
}

.sd-order-line__options {
  color: var(--sd-order-line-options-foreground);
  overflow-wrap: anywhere;
}

.sd-order-line__discount {
  display: inline-flex;
  align-items: center;
  gap: var(--sd-order-line-summary-gap);
  color: var(--sd-order-line-discount-foreground);
}

.sd-order-line__price {
  grid-area: price;
  display: flex;
  flex-direction: column;
  align-items: end;
  color: var(--sd-order-line-price-foreground);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.sd-order-line__original-price {
  color: var(--sd-order-line-original-price-foreground);
}

.sd-order-line__name[data-muted],
.sd-order-line__discount[data-muted],
.sd-order-line__price[data-muted] {
  color: var(--sd-order-line-muted-foreground);
}

.sd-order-line__remove {
  grid-area: remove;
}

.sd-order-line__actions {
  grid-area: actions;
  display: flex;
  flex-wrap: wrap;
  justify-content: end;
  align-items: center;
  gap: var(--sd-order-line-gap);
}

.sd-order-line__actions[data-controls="top"] {
  justify-content: start;
}

/* The stepper keeps its fixed width as a floor and widens with its own size's control height, so a
   usage context's taller step chips never squeeze the value out (three heights: one per step chip, one for the value). */
.sd-order-line__stepper {
  inline-size: var(--sd-order-line-stepper-width);
}
.sd-order-line__stepper[data-size="small"] {
  inline-size: max(var(--sd-order-line-stepper-width), calc(var(--sd-order-line-stepper-span) * var(--sd-order-line-stepper-height-small)));
}
.sd-order-line__stepper[data-size="medium"] {
  inline-size: max(var(--sd-order-line-stepper-width), calc(var(--sd-order-line-stepper-span) * var(--sd-order-line-stepper-height-medium)));
}
.sd-order-line__stepper[data-size="large"] {
  inline-size: max(var(--sd-order-line-stepper-width), calc(var(--sd-order-line-stepper-span) * var(--sd-order-line-stepper-height-large)));
}
.sd-order-line__stepper[data-size="x-large"] {
  inline-size: max(var(--sd-order-line-stepper-width), calc(var(--sd-order-line-stepper-span) * var(--sd-order-line-stepper-height-x-large)));
}
